import { useState } from "react";

function DongY() {
  const [check, setCheck] = useState(false);
  return (
    <label>
      <input
        type="checkbox"
        checked={check}
        onChange={(e) => setCheck(e.target.checked)}
      />
      {check ? "Da dong y" : "Chua dong y"}
    </label>
  );
}

export default DongY;
